"""Data schemas and profile models for the AuditPilot multi-agent audit system."""

import math
from datetime import datetime
from typing import Any, Literal
from pydantic import BaseModel, Field


class DataProfile(BaseModel):
    """Structured data profile generated by the intake_agent.

    Captures file validation, double-entry mathematical balance, fiscal period
    boundaries, and trial balance reconciliation status.
    """

    status: Literal["PASSED", "PASSED_WITH_VARIANCE", "FAILED"] = Field(
        ...,
        description=(
            "Status of data intake: 'FAILED' if files are missing, unreadable, or missing columns, "
            "or if numeric values, dates, row count, double-entry balance, or reconciliation are invalid or incomplete; "
            "'PASSED_WITH_VARIANCE' if files are structurally valid and balanced but trial balance discrepancies exist; "
            "'PASSED' if all files are valid and trial balance reconciles with zero discrepancy."
        ),
    )
    failure_reasons: list[str] = Field(
        default_factory=list,
        description="List of specific failure reasons if status is FAILED.",
    )
    row_count: int | None = Field(
        default=None,
        description="Total row count of the general ledger.",
    )
    column_count: int | None = Field(
        default=None,
        description="Number of columns present in the general ledger.",
    )
    total_debit_inr: float | None = Field(
        default=None,
        description="Total debit sum across the general ledger in INR.",
    )
    total_credit_inr: float | None = Field(
        default=None,
        description="Total credit sum across the general ledger in INR.",
    )
    is_balanced: bool | None = Field(
        default=None,
        description="True if total debits equal total credits within tolerance.",
    )
    start_date: str | None = Field(
        default=None,
        description="Earliest transaction date found in the general ledger (YYYY-MM-DD).",
    )
    end_date: str | None = Field(
        default=None,
        description="Latest transaction date found in the general ledger (YYYY-MM-DD).",
    )
    trial_balance_reconciled: bool | None = Field(
        default=None,
        description="True if all accounts in trial balance match ledger account totals.",
    )
    trial_balance_gap_inr: float | None = Field(
        default=None,
        description="Total monetary gap between ledger and trial balance across all accounts in INR.",
    )
    flagged_ids: list[str] = Field(
        default_factory=list,
        description="Journal entry IDs identified during intake (e.g. trial balance gap candidates).",
    )
    trial_balance_discrepancies: list[dict[str, Any]] = Field(
        default_factory=list,
        description="Account-level discrepancies returned by the trial balance reconciliation tool.",
    )
    notes: str = Field(
        ...,
        description="Detailed summary notes explaining validation and reconciliation findings.",
    )

class Finding(BaseModel):
    """Structured audit finding with likelihood and impact scoring."""

    id: str
    category: str
    title: str

    entry_ids: list[str] = Field(
        ...,
        min_length=1,
        description="Journal entry IDs supporting this finding.",
    )

    evidence: list[str] = Field(default_factory=list)

    amount_at_risk_inr: float = Field(
        default=0.0,
        ge=0,
        description="Financial exposure calculated by a deterministic tool.",
    )

    likelihood: int = Field(
        ...,
        ge=1,
        le=5,
        description="Likelihood of the identified risk, from 1 to 5.",
    )

    impact: int = Field(
        ...,
        ge=1,
        le=5,
        description="Impact of the identified risk, from 1 to 5.",
    )

    score: int = Field(
        default=0,
        ge=0,
        le=25,
        description="Deterministic risk score: likelihood multiplied by impact.",
    )

    rationale: str
    review_reason: str | None = None

    status: Literal[
        "pending",
        "confirmed",
        "needs_evidence",
        "dropped",
    ] = "pending"


class RankedFindings(BaseModel):
    """Structured collection of ranked audit findings."""

    findings: list[Finding]
    total_findings: int = Field(ge=0)
    total_amount_at_risk_inr: float = Field(ge=0)

class SkepticReview(BaseModel):
    """Skeptic's review decision for one audit finding."""

    finding_id: str
    status: Literal["confirmed", "needs_evidence", "dropped"]
    review_reason: str


class SkepticReviewBatch(BaseModel):
    """Collection of skeptic decisions for the ranked findings."""

    reviews: list[SkepticReview]


def _require_finite_non_negative(
    value: Any,
    field_name: str,
    failure_reasons: list[str],
) -> bool:
    """Validate that a value is a finite, non-negative number (not a bool).
    Appends to failure_reasons and returns False if invalid."""
    if value is None:
        failure_reasons.append(f"Required field '{field_name}' is missing.")
        return False
    if isinstance(value, bool):
        failure_reasons.append(f"'{field_name}' must be a numeric value, not a boolean.")
        return False
    if not isinstance(value, (int, float)):
        failure_reasons.append(f"'{field_name}' must be numeric, got {type(value).__name__}.")
        return False
    if not math.isfinite(value):
        failure_reasons.append(f"'{field_name}' must be a finite number, got {value}.")
        return False
    if value < 0:
        failure_reasons.append(f"'{field_name}' must be non-negative, got {value}.")
        return False
    return True


def build_data_profile(
    ledger_res: dict[str, Any] | None,
    tb_res: dict[str, Any] | None,
) -> DataProfile:
    """Deterministically builds a DataProfile from load_ledger and check_trial_balance results.

    Fail-Closed Validation Rules:
    - FAILED: Missing, empty, or invalid tool results; incorrectly named tests; missing files;
      missing or false is_valid; invalid schema; invalid/non-finite numeric values; invalid/out-of-FY dates;
      incorrect row count; unbalanced ledger; missing critical statistics; or missing/unsuccessful reconciliation.
    - PASSED_WITH_VARIANCE: All tool results valid and ledger balanced, but trial balance has a verified discrepancy.
    - PASSED: All tool results valid, ledger balanced, and trial balance fully reconciles.
    """
    failure_reasons: list[str] = []

    # ── 1. Validate ledger_res structure and test identifier ──────────────────
    if not isinstance(ledger_res, dict):
        failure_reasons.append("Ledger result is missing or not a dictionary.")
        load_stats: dict[str, Any] = {}
    elif ledger_res.get("test") != "load_ledger":
        failure_reasons.append(
            f"Ledger result 'test' must be 'load_ledger', got '{ledger_res.get('test')}'."
        )
        load_stats = ledger_res.get("stats", {}) if isinstance(ledger_res.get("stats"), dict) else {}
    elif not isinstance(ledger_res.get("stats"), dict):
        failure_reasons.append("Ledger result missing valid 'stats' dictionary.")
        load_stats = {}
    else:
        load_stats = ledger_res["stats"]

    # ── 2. Validate tb_res structure and test identifier ──────────────────────
    if not isinstance(tb_res, dict):
        failure_reasons.append("Trial balance result is missing or not a dictionary.")
        tb_stats: dict[str, Any] = {}
    elif tb_res.get("test") != "check_trial_balance":
        failure_reasons.append(
            f"Trial balance result 'test' must be 'check_trial_balance', got '{tb_res.get('test')}'."
        )
        tb_stats = tb_res.get("stats", {}) if isinstance(tb_res.get("stats"), dict) else {}
    elif not isinstance(tb_res.get("stats"), dict):
        failure_reasons.append("Trial balance result missing valid 'stats' dictionary.")
        tb_stats = {}
    else:
        tb_stats = tb_res["stats"]

    # ── 3. File existence flags (conditional — only reject if explicitly wrong) ─
    # Phase 2 successful tool outputs omit these keys; we only fail on explicit
    # False, None, or non-boolean values. Absence alone is not an error here.
    if "file_exists" in load_stats:
        if load_stats["file_exists"] is not True:
            failure_reasons.append(
                f"Ledger 'file_exists' must be True, got {load_stats['file_exists']!r}."
            )
    if "ledger_exists" in tb_stats:
        if tb_stats["ledger_exists"] is not True:
            failure_reasons.append(
                f"Trial balance 'ledger_exists' must be True, got {tb_stats['ledger_exists']!r}."
            )
    if "tb_exists" in tb_stats:
        if tb_stats["tb_exists"] is not True:
            failure_reasons.append(
                f"Trial balance 'tb_exists' must be True, got {tb_stats['tb_exists']!r}."
            )

    # ── 4. Require is_valid: True from load_ledger stats ─────────────────────
    is_valid = load_stats.get("is_valid")
    if not isinstance(is_valid, bool):
        failure_reasons.append(
            f"Ledger stats 'is_valid' must be an explicit boolean, got {is_valid!r}."
        )
    elif is_valid is not True:
        failure_reasons.append(
            "Ledger stats 'is_valid' is False — ledger failed Phase 2 validation."
        )

    # ── 5. Schema checks (missing required columns) ───────────────────────────
    if load_stats.get("missing_columns"):
        failure_reasons.append(f"Ledger missing required columns: {load_stats['missing_columns']}")
    if tb_stats.get("tb_missing_columns"):
        failure_reasons.append(f"Trial balance missing required columns: {tb_stats['tb_missing_columns']}")
    if tb_stats.get("ledger_missing_columns"):
        failure_reasons.append(f"Ledger missing required columns for reconciliation: {tb_stats['ledger_missing_columns']}")

    # ── 6. Finite numeric validation on required monetary fields ──────────────
    total_debit = load_stats.get("total_debit_inr")
    debit_ok = _require_finite_non_negative(total_debit, "total_debit_inr", failure_reasons)

    total_credit = load_stats.get("total_credit_inr")
    credit_ok = _require_finite_non_negative(total_credit, "total_credit_inr", failure_reasons)

    # balance_difference_inr: required when totals are present (optional sentinel)
    diff = load_stats.get("balance_difference_inr")
    if diff is not None:
        if isinstance(diff, bool) or not isinstance(diff, (int, float)) or not math.isfinite(diff):
            failure_reasons.append(
                f"'balance_difference_inr' must be a finite number, got {diff!r}."
            )

    total_discrepancy = tb_stats.get("total_discrepancy_inr")
    discrepancy_ok = _require_finite_non_negative(total_discrepancy, "total_discrepancy_inr", failure_reasons)

    # ── 7. date_violations_count — mandatory non-negative int, no default ─────
    date_violations = load_stats.get("date_violations_count")
    if date_violations is None:
        failure_reasons.append("Ledger stats 'date_violations_count' is missing.")
        date_violations = None
    elif isinstance(date_violations, bool):
        failure_reasons.append(f"'date_violations_count' must be an integer, not a boolean.")
        date_violations = None
    elif not isinstance(date_violations, int) or date_violations < 0:
        failure_reasons.append(
            f"'date_violations_count' must be a non-negative integer, got {date_violations!r}."
        )
        date_violations = None
    elif date_violations > 0:
        fy_range = load_stats.get("fiscal_year_range", "FY 2025-26")
        failure_reasons.append(
            f"Ledger contains {date_violations} date violations outside fiscal year range ({fy_range})."
        )

    # ── 8. numeric_errors — mandatory dict of non-negative int counts ─────────
    numeric_errors = load_stats.get("numeric_errors")
    if numeric_errors is None:
        failure_reasons.append("Ledger stats 'numeric_errors' dictionary is missing.")
    elif not isinstance(numeric_errors, dict):
        failure_reasons.append(
            f"'numeric_errors' must be a dictionary, got {type(numeric_errors).__name__}."
        )
    else:
        for col_name, err_count in numeric_errors.items():
            if isinstance(err_count, bool):
                failure_reasons.append(
                    f"numeric_errors['{col_name}'] must be an integer, not a boolean."
                )
            elif not isinstance(err_count, int) or err_count < 0:
                failure_reasons.append(
                    f"numeric_errors['{col_name}'] must be a non-negative integer, got {err_count!r}."
                )
            elif err_count > 0:
                failure_reasons.append(
                    f"Ledger contains {err_count} non-numeric value(s) in column '{col_name}'."
                )

    # ── 9. Row count and boolean flags ────────────────────────────────────────
    row_count = load_stats.get("row_count")
    if row_count is None or isinstance(row_count, bool) or not isinstance(row_count, int) or row_count <= 0:
        failure_reasons.append(
            f"Ledger stats 'row_count' must be a positive integer, got {row_count!r}."
        )

    column_count = load_stats.get("column_count")
    if column_count is None or isinstance(column_count, bool) or not isinstance(column_count, int) or column_count <= 0:
        failure_reasons.append(
            f"Ledger stats 'column_count' must be a positive integer, got {column_count!r}."
        )

    row_count_valid = load_stats.get("row_count_valid")
    if not isinstance(row_count_valid, bool):
        failure_reasons.append(
            f"Ledger stats 'row_count_valid' must be an explicit boolean, got {row_count_valid!r}."
        )
    elif row_count_valid is not True:
        failure_reasons.append(
            f"Ledger row_count_valid is False (expected {load_stats.get('expected_row_count')}, got {row_count})."
        )

    is_balanced = load_stats.get("is_balanced")
    if not isinstance(is_balanced, bool):
        failure_reasons.append(
            f"Ledger stats 'is_balanced' must be an explicit boolean, got {is_balanced!r}."
        )
    elif is_balanced is not True:
        bal_diff = load_stats.get("balance_difference_inr")
        if bal_diff is not None and isinstance(bal_diff, (int, float)) and not isinstance(bal_diff, bool) and math.isfinite(bal_diff):
            failure_reasons.append(
                f"Ledger double-entry is unbalanced by Rs {bal_diff:,.2f} (is_balanced is False)."
            )
        else:
            failure_reasons.append("Ledger is_balanced is False.")

    # ── 10. Trial balance required statistics ─────────────────────────────────
    accounts_reconciled = tb_stats.get("accounts_reconciled")
    if (
        accounts_reconciled is None
        or isinstance(accounts_reconciled, bool)
        or not isinstance(accounts_reconciled, int)
        or accounts_reconciled <= 0
    ):
        failure_reasons.append(
            f"Trial balance stats 'accounts_reconciled' must be a positive integer, got {accounts_reconciled!r}."
        )

    discrepant_count = tb_stats.get("discrepant_accounts_count")
    if (
        discrepant_count is None
        or isinstance(discrepant_count, bool)
        or not isinstance(discrepant_count, int)
        or discrepant_count < 0
    ):
        failure_reasons.append(
            f"Trial balance stats 'discrepant_accounts_count' must be a non-negative integer, got {discrepant_count!r}."
        )

    reconciled = tb_stats.get("reconciled")
    if not isinstance(reconciled, bool):
        failure_reasons.append(
            f"Trial balance stats 'reconciled' must be an explicit boolean, got {reconciled!r}."
        )

    if tb_stats.get("invalid_numeric_tb_accounts"):
        failure_reasons.append(
            f"Trial balance contains invalid non-numeric balances on accounts: {tb_stats['invalid_numeric_tb_accounts']}"
        )
    if tb_stats.get("invalid_numeric_gl_entries"):
        failure_reasons.append(
            f"Ledger contains non-numeric entries during reconciliation: {tb_stats['invalid_numeric_gl_entries']}"
        )

    # ── 11. Parseable dates and start_date <= end_date ────────────────────────
    start_date_str = load_stats.get("start_date")
    end_date_str = load_stats.get("end_date")
    start_dt: datetime | None = None
    end_dt: datetime | None = None

    if not isinstance(start_date_str, str) or not start_date_str.strip():
        failure_reasons.append("Ledger stats 'start_date' is missing or empty.")
    else:
        try:
            start_dt = datetime.strptime(start_date_str.strip(), "%Y-%m-%d")
        except ValueError:
            failure_reasons.append(
                f"'start_date' '{start_date_str}' is not a valid YYYY-MM-DD date."
            )

    if not isinstance(end_date_str, str) or not end_date_str.strip():
        failure_reasons.append("Ledger stats 'end_date' is missing or empty.")
    else:
        try:
            end_dt = datetime.strptime(end_date_str.strip(), "%Y-%m-%d")
        except ValueError:
            failure_reasons.append(
                f"'end_date' '{end_date_str}' is not a valid YYYY-MM-DD date."
            )

    if start_dt is not None and end_dt is not None and start_dt > end_dt:
        failure_reasons.append(
            f"start_date ({start_date_str}) cannot be later than end_date ({end_date_str})."
        )

    # ── 12. Reconciliation consistency check ──────────────────────────────────
    # Only check when both values are known-good
    if (
        isinstance(discrepant_count, int) and not isinstance(discrepant_count, bool)
        and discrepancy_ok
    ):
        if discrepant_count == 0 and total_discrepancy > 0.01:
            failure_reasons.append(
                f"Inconsistent reconciliation: 0 discrepant accounts but total discrepancy is "
                f"Rs {total_discrepancy:,.2f}."
            )
        elif discrepant_count > 0 and total_discrepancy <= 0.01:
            failure_reasons.append(
                f"Inconsistent reconciliation: {discrepant_count} discrepant accounts but "
                f"total discrepancy is Rs {total_discrepancy:,.2f}."
            )

    if isinstance(reconciled, bool) and isinstance(discrepant_count, int) and not isinstance(discrepant_count, bool) and discrepancy_ok:
        if reconciled is True and (discrepant_count > 0 or total_discrepancy > 0.01):
            failure_reasons.append(
                f"Inconsistent reconciliation: reconciled=True but discrepant_accounts_count="
                f"{discrepant_count} and total_discrepancy_inr=Rs {total_discrepancy:,.2f}."
            )

    # ── 13. Status classification ──────────────────────────────────────────────
    if failure_reasons:
        status = "FAILED"
    elif (
        isinstance(reconciled, bool)
        and reconciled is False
        and isinstance(discrepant_count, int)
        and discrepant_count > 0
        and discrepancy_ok
        and total_discrepancy > 0.01
    ):
        status = "PASSED_WITH_VARIANCE"
    elif (
        isinstance(reconciled, bool)
        and reconciled is True
        and isinstance(discrepant_count, int)
        and discrepant_count == 0
        and discrepancy_ok
        and total_discrepancy <= 0.01
    ):
        status = "PASSED"
    else:
        status = "FAILED"
        failure_reasons.append("Trial balance reconciliation state is inconsistent or unverified.")

    # ── 14. Gather flagged IDs ────────────────────────────────────────────────
    flagged_ids = sorted(list(set(
        (ledger_res.get("flagged_ids", []) if isinstance(ledger_res, dict) and isinstance(ledger_res.get("flagged_ids"), list) else []) +
        (tb_res.get("flagged_ids", []) if isinstance(tb_res, dict) and isinstance(tb_res.get("flagged_ids"), list) else [])
    )))

    notes_parts = []
    if isinstance(ledger_res, dict) and ledger_res.get("notes"):
        notes_parts.append(str(ledger_res["notes"]))
    if isinstance(tb_res, dict) and tb_res.get("notes"):
        notes_parts.append(str(tb_res["notes"]))
    combined_notes = " | ".join(notes_parts) if notes_parts else "Data intake profiling complete."

    return DataProfile(
        status=status,
        failure_reasons=failure_reasons,
        row_count=row_count if isinstance(row_count, int) and not isinstance(row_count, bool) else None,
        column_count=column_count if isinstance(column_count, int) and not isinstance(column_count, bool) else None,
        total_debit_inr=float(total_debit) if debit_ok else None,
        total_credit_inr=float(total_credit) if credit_ok else None,
        is_balanced=is_balanced if isinstance(is_balanced, bool) else None,
        start_date=start_date_str if start_dt is not None else None,
        end_date=end_date_str if end_dt is not None else None,
        trial_balance_reconciled=reconciled if isinstance(reconciled, bool) else None,
        trial_balance_gap_inr=float(total_discrepancy) if discrepancy_ok else None,
        flagged_ids=flagged_ids,
        trial_balance_discrepancies=(
        tb_res.get("stats", {}).get("discrepancies", [])
       if isinstance(tb_res, dict) and isinstance(tb_res.get("stats"), dict)
        else []
    ),
    notes=combined_notes,
    )
